---@class GoFishFishingState
local GoFishFishingState = Class("GoFishFishingState", GoFishBaseState)

function GoFishFishingState:__init(view)
    self._fishFinishEvent = Events.AddListener(Constants.EventNames.FishFinish, Bind(self, self.OnFishFinish))
    self.TransferTo = view.TransferTo
    for k, v in pairs(view) do
        self[k] = v
    end
end

function GoFishFishingState:__delete()
    if self._fishFinishEvent then
        Events.RemoveListener(Constants.EventNames.FishFinish, self._fishFinishEvent)
        self._fishFinishEvent = nil
    end

end

function GoFishFishingState:CanTransfer(target)
    return true
end

function GoFishFishingState:OnEnter(params)
    self.isAuto = params.isAuto
    local fishId = params.fishId
    local type = params.type

    self.roleAnimServer:ChangeRoleStatus(ConstantsFishing.RoleStatus.Fishing)
    self.fishingGoodsServer:ShowMe()
    self.fishDisplayServer:UpdateInfo()
    self.startFishingServer:ShowMe()
    self.damageBarServer:ShowMe()
    self.fishLineServer:ShowMe()
    self.fishBloodServer:ShowMe()
    self.leftPanelServer:IsBlockClick(true)

    self.fishDisplayServer:SetCurQTEPos(50)

    CfUtils.SetUISwitchImage(self.ImgFishing, 2)
    CfUtils.SetUISwitchImage(self.TextPullPole, 2)

    FishingMgr:GetInstance():InitFishingData(fishId, self.placeId, nil, function(talkType, para)
        self.leftPanelServer:RefreshRoleTalk(talkType, para)
    end, self._isGuide, function()
        self.damageBarServer:RefreshDamageInfo()
    end)


    --CfUtils.PlayAnimator(self.Root, "Show")
    CfUtils.PlayAnimator(self.Root, "FishingGoodsShow")
    if self.isAuto then
        self.autoFishPanelServer:ShowMe()
    else
        self.autoFishPanelServer:HideMe()
    end

    self.btnFishingGroupServer:HideMe()
    self.btnLeaveServer:ShowMe()
    CfUtils.SetActive(self.CommonPrivilegeCardNode, false)
    CfUtils.SetActive(self.BtnFishNet, false)
end

function GoFishFishingState:OnExit()
    self.startFishingServer:HideMe()
end

function GoFishFishingState:Update()

    self.roleAnimServer:OnUpdate()
    self.startFishingServer:OnUpdate()
    self.btnLeaveServer:OnUpdate()
    self.fishDisplayServer:OnUpdate()
    self.fishLineServer:OnUpdate()
    self.autoFishPanelServer:OnUpdate()
end

--钓鱼结束
function GoFishFishingState:OnFishFinish(body)
    body.isAuto = self.isAuto
    if self.isAuto then
        if body.type ~= ConstantsFishing.FishFinishType.Success then
            Events.Broadcast("AutoFishFailed")
        end
    end
    self.TransferTo(EGoFishState.End, body)
end



return GoFishFishingState